+        constexpr char kManifestPath[] = "/quickstart_manifest.json";
+    } // namespace
+
+    bool ensureSpiffs()
+    {
+        static bool mounted = false;
+        if (!mounted)
+        {
+            mounted = SPIFFS.begin(true);
